          workAreas800.setSub5800((short) 0);
//  ADD 310-BINARY-ONE TO 800-SUB3
          workAreas800.setSub3800( (short) (workAreas800.getSub3800()+work.getBinaryOne310()));

// *    * Loop through xtk parm text, parse value
