			TarafxsSrcTaskUsr tarafxsSrcTaskUsr = tarafxs.getTarafxsSrcTaskUsr();
			TarafxsTrgtTaskUsr tarafxsTrgtTaskUsr = tarafxs.getTarafxsTrgtTaskUsr();
