      private void setupPostExitDsn() throws Exception {
			// Declare local variables used in the method
			int loop = 0;
			int pointerCnt = 0;
			String updatedRegEx = null;
			char[] resultKey = null;
			char[] resultValue = null;
			char[] padArr = new char[] {' '};
			char[] plusSign = new char[] {'+'};
			char[] actualUnstringStr = null;
			char[] broadcastEndptQual320 = null;
			char[] joinCharArray = null;
			ArrayList<String> splitBy = null;
			List<Pair> result = null;
			ApplExitWork810 applExitWork810 = reqWorkAreas810.getApplExitWork810();
			GftdsnHlqid820 gftdsnHlqid820 = gftdsnWorkAreas820.getGftdsnHlqid820();
			ArrayList<char[]> charArray = new ArrayList<char[]>();
			Map<String,Object> updated = null;
			// End of variable declaration

      
// *    Setup post-application exit dsn                             *
// ******************************************************************
//  MOVE SPACES TO 550-DSN-QUAL-TABLE
          dsnQualTable550.setString(CONSTANTS.SPACE_64);
//  UNSTRING 810-PRE-EXIT-DSN DELIMITED BY '.' OR ALL SPACES INTO 550-DSN-QUAL (1) 550-DSN-QUAL (2) 550-DSN-QUAL (3) 550-DSN-QUAL (4) 550-DSN-QUAL (5) 550-DSN-QUAL (6) 550-DSN-QUAL (7) 550-DSN-QUAL (8) END-UNSTRING
          //This will have the no of characters parsed while un string. On NoOverflow pointerCnt == actualstring.length
          actualUnstringStr = reqWorkAreas810.getPreExitDsn810();
          //Construct an ArrayList by the given Delimited String. '+' will be added when there is ALL.EG ALL $, then delimited String will be $+
          splitBy = getArrayList(CONSTANTS.LITERAL_34134,addArrays(CONSTANTS.SPACE,plusSign));
          //Create a RegularExpression String from the above delimited list (updateRegEx will add escape character \\ if in need, also group the values when required)
          updatedRegEx = updateRegEx(splitBy);
          //Split and store the String and delimited values.(EG : AABC$$$GH%, delimited by = ALL $, %, then result will have AABC - $ , GH - %)
          result = splitString(actualUnstringStr,updatedRegEx);
          loop = 0;
          try{
          	resultKey = (char[])result.get(loop).getKey();
          	resultValue = (char[])result.get(loop).getValue();
          	dsnQualTable550.setDsnQual550(0,resultKey);
          	
          	loop++;
          	resultKey = (char[])result.get(loop).getKey();
          	resultValue = (char[])result.get(loop).getValue();
          	dsnQualTable550.setDsnQual550(1,resultKey);
          	
          	loop++;
          	resultKey = (char[])result.get(loop).getKey();
          	resultValue = (char[])result.get(loop).getValue();
          	dsnQualTable550.setDsnQual550(2,resultKey);
          	
          	loop++;
          	resultKey = (char[])result.get(loop).getKey();
          	resultValue = (char[])result.get(loop).getValue();
          	dsnQualTable550.setDsnQual550(3,resultKey);
          	
          	loop++;
          	resultKey = (char[])result.get(loop).getKey();
          	resultValue = (char[])result.get(loop).getValue();
          	dsnQualTable550.setDsnQual550(4,resultKey);
          	
          	loop++;
          	resultKey = (char[])result.get(loop).getKey();
          	resultValue = (char[])result.get(loop).getValue();
          	dsnQualTable550.setDsnQual550(5,resultKey);
          	
          	loop++;
          	resultKey = (char[])result.get(loop).getKey();
          	resultValue = (char[])result.get(loop).getValue();
          	dsnQualTable550.setDsnQual550(6,resultKey);
          	
          	loop++;
          	resultKey = (char[])result.get(loop).getKey();
          	resultValue = (char[])result.get(loop).getValue();
          	dsnQualTable550.setDsnQual550(7,resultKey);
          	
          	loop++;
          }
          catch(IndexOutOfBoundsException e ){
          	//logger.info(e.getMessage());
          }
          broadcastEndptQual320 = characterLiterals320.getBroadcastEndptQual320();
//  IF 550-DSN-QUAL (5) = 320-BROADCAST-ENDPT-QUAL
          if (		compareChars(dsnQualTable550.getDsnQual550(4),broadcastEndptQual320) == 0 ) { 
//  PERFORM 2821-SETUP-INSTALL-BROADCAST
              setupInstallBroadcast();/*2821-SETUP-INSTALL-BROADCAST*/
          }
  
//  ELSE
          else { 
//  PERFORM 2822-SETUP-INSTALL-STANDARD
              setupInstallStandard();/*2822-SETUP-INSTALL-STANDARD*/
          }
//  MOVE 810-APPL-EXIT-MBR TO 550-DSN-QUAL (5)
          dsnQualTable550.setDsnQual550(4,applExitWork810.getApplExitMbr810());
  
//  MOVE 820-GFTDSN-HLQID TO 530-SPEC-DSN ( 530-SPEC-TRGT )
          specTable530.getSpecEntry530(specTrgt530 - 1).getSpecFile530().setSpecDsn530(pad(44,gftdsnWorkAreas820.getGftdsnHlqid820().toCharArray(),SPACE_CHAR,RIGHT_PAD));
          gftdsnHlqid820 = gftdsnWorkAreas820.getGftdsnHlqid820();
//  IF 88-820-GFTDSN-HLQID-LEN-3
          if ( gftdsnHlqid820.isGftdsnHlqidLen388820()  ) { 
//  MOVE 310-BINARY-FOUR TO 800-SUB
              workAreas800.setSub800(work.getBinaryFour310());
          }
  
//  ELSE
          else { 
//  MOVE 310-BINARY-FIVE TO 800-SUB
              workAreas800.setSub800(work.getBinaryFive310());
          }
//  PERFORM VARYING 550-DSN FROM 2 BY 1 UNTIL 550-DSN > 8 OR 550-DSN-QUAL ( 550-DSN ) = SPACES
          for (dsn550 = 2; (	( dsn550 <= 8 ) &&         ( !allSpaces(dsnQualTable550.getDsnQual550(dsn550 - 1))  )) ; dsn550 = dsn550 + 1 ) {
//  STRING 320-PERIOD DELIMITED BY SIZE 550-DSN-QUAL ( 550-DSN ) DELIMITED BY SPACE INTO 530-SPEC-DSN ( 530-SPEC-TRGT ) WITH POINTER 800-SUB END-STRING
              charArray = new ArrayList<char[]>();
                 charArray.add(characterLiterals320.getPeriod320());
                 charArray.add(splitFirst( dsnQualTable550.getDsnQual550(dsn550 - 1) , CONSTANTS.SPACE ) );
              joinCharArray = Field.mergeArrays(charArray.get(0),charArray.get(1));
              updated = updateString(specTable530.getSpecEntry530(specTrgt530 - 1).getSpecFile530().getSpecDsn530() ,joinCharArray ,(workAreas800.getSub800()-1));
              specTable530.getSpecEntry530(specTrgt530 - 1).getSpecFile530().setSpecDsn530(   (char[])updated.get("string"));
              workAreas800.setSub800((int)updated.get("startAt"));
          }
      
      }
