//  SET 88-1000-REQUEST-SUCCESSFUL TO TRUE
                  responseParms1000.setRequestSuccessful881000True(); 
                  
//  SET 88-530-SPEC-STAT-OPENED ( 530-SPEC-SRCE ) TO TRUE
                  specTable530.getSpecEntry530(specSrce530 - 1).setSpecStatOpened88530True(); 
                  
