      private void rollbackActivity() throws Exception {
			// Declare local variables used in the method
			int sqlcode = 0;
			short sqlSuccess330 = 0;
			// End of variable declaration

      
// *    Rollback function's activity                                *
// ******************************************************************
//  SET 88-110-SQL-EXEC-START TO TRUE
          work.setSqlExecStart88110True(); 
          
//  PERFORM UNTIL 88-110-SQL-EXEC-END
          while ((!(work.isSqlExecEnd88110()) )) {
//  ROLLBACK
              try {
              	// COMMIT
              	// reset SQLCODE
              	sqlca.setSqlcode(0);
                 // execute jdbc commit
                 db2Base.rollback();
              }
               catch (SQLException e) {
                         sqlca.setSqlcode(Db2Base.fillSQLCode(e.getMessage()));
                     }
               catch(Exception e) {
                handleErrorCode(e);
              }
              sqlcode = sqlca.getSqlcode();
//  IF SQLCODE NEGATIVE
              if (            ( sqlcode < 0 )) { 
//  PERFORM 8999-CHECK-SQL-RETRY
                  checkSqlRetry();/*8999-CHECK-SQL-RETRY*/
              }
  
//  ELSE
              else { 
//  SET 88-110-SQL-EXEC-END TO TRUE
                  work.setSqlExecEnd88110True(); 
                  
              }
          }
//  IF SQLCODE = 330-SQL-SUCCESS
          sqlSuccess330 = work.getSqlSuccess330();
          sqlcode = sqlca.getSqlcode();
//  ELSE
          if (	( sqlcode != sqlSuccess330 ) ) { 

// *        * Report release error *
//  SET 88-1000-CONN-GFTDB-ROLLBACK TO TRUE
              responseParms1000.setConnGftdbRollback881000True(); 
              
//  PERFORM 9400-REPORT-SQL-ERROR
              reportSqlError();/*9400-REPORT-SQL-ERROR*/
          }
  
      
      }
