      /**
      * computeJulianDay 
      *   This method is derived from 
  *   COBOL Paragraph - 8071-COMPUTE-JULIAN-DAY COBOL Cyclomatic complexity - 3
      * Input  :  

      * - procYear810                    COBOL Name: 810-PROC-YEAR
      * - procMonth810                   COBOL Name: 810-PROC-MONTH
      * - procDay810                     COBOL Name: 810-PROC-DAY
      * - zonedTwentynine310             COBOL Name: 310-ZONED-TWENTYNINE
      * - zonedTwentyeight310            COBOL Name: 310-ZONED-TWENTYEIGHT
      *
      * Output :  

      * - jan1stDate800                  COBOL Name: 800-JAN-1ST-DATE
      * - computeDate810                 COBOL Name: 810-COMPUTE-DATE
      * - procYear810                    COBOL Name: 810-PROC-YEAR
      * - procMonth810                   COBOL Name: 810-PROC-MONTH
      * - procDay810                     COBOL Name: 810-PROC-DAY
      * - daysInMonth560                 COBOL Name: 560-DAYS-IN-MONTH
      * - zonedTwentynine310             COBOL Name: 310-ZONED-TWENTYNINE
      * - zonedTwentyeight310            COBOL Name: 310-ZONED-TWENTYEIGHT
      * - functionResponse1000           COBOL Name: 1000-FUNCTION-RESPONSE
      * - procJulDay810                  COBOL Name: 810-PROC-JUL-DAY
      *
      * @throws CFException
      */
      private void computeJulianDay() throws Exception {
			// Declare local variables used in the method
			ProcDate810 procDate810 = reqWorkAreas810.getProcDate810();
			int procDay810 = 0;
			// End of variable declaration

      
// *    Compute processing date's julian day                        *
// ******************************************************************

// *    Set up processing date for julian day computation
//  MOVE 810-PROC-YEAR TO 800-JAN-1ST-DATE (1 : 4) 810-COMPUTE-DATE (1 : 4)
          workAreas800.setJan1stDate800(replace(String.valueOf(workAreas800.getJan1stDate800String()).toCharArray(),String.valueOf(procDate810.getProcYear810String()).toCharArray(),0,4));
          reqWorkAreas810.setComputeDate810(replace(String.valueOf(reqWorkAreas810.getComputeDate810String()).toCharArray(),String.valueOf(procDate810.getProcYear810String()).toCharArray(),0,4));
  
//  MOVE 810-PROC-MONTH TO 810-COMPUTE-DATE (5 : 2)
          reqWorkAreas810.setComputeDate810(replace(String.valueOf(reqWorkAreas810.getComputeDate810String()).toCharArray(),String.valueOf(procDate810.getProcMonth810String()).toCharArray(),4,6));
  
//  MOVE 810-PROC-DAY TO 810-COMPUTE-DATE (7 : 2)
          reqWorkAreas810.setComputeDate810(replace(String.valueOf(reqWorkAreas810.getComputeDate810String()).toCharArray(),String.valueOf(procDate810.getProcDay810String()).toCharArray(),6,8));
  

// *    Set up days-in-month table based on leap or non-leap year

// *        Leap year has 29 days in february
//  IF FUNCTION REM ( 810-PROC-YEAR 4) = ZERO
          if (	( procDate810.getProcYear810() % 4 == 0 )) { 
//  MOVE 310-ZONED-TWENTYNINE TO 560-DAYS-IN-MONTH (2)
              daysInMonthTable560.setDaysInMonth560(1,work.getZonedTwentynine310());
          }
  
//  ELSE
          else { 

// *        Non-leap year has 28 days in february
//  MOVE 310-ZONED-TWENTYEIGHT TO 560-DAYS-IN-MONTH (2)
              daysInMonthTable560.setDaysInMonth560(1,work.getZonedTwentyeight310());
          }

// *    Check if processing 'day' is valid for this year & month

// *        Processing day of month is invalid
          procDay810 = procDate810.getProcDay810();
//  IF 810-PROC-DAY > 560-DAYS-IN-MONTH ( 810-PROC-MONTH )
          if (	( procDay810 > daysInMonthTable560.getDaysInMonth560(procDate810.getProcMonth810() - 1) )) { 
//  SET 88-1000-PARM-PROCDATE-DOM TO TRUE
              responseParms1000.setParmProcdateDom881000True(); 
              
//  PERFORM 9110-REPORT-PARM-ERROR
              reportParmError();/*9110-REPORT-PARM-ERROR*/
          }
  
//  ELSE
          else { 
              reqWorkAreas810.setProcJulDay810((int)Math.abs((int) CFUtil.integerOfDate((int) reqWorkAreas810.getComputeDate810()) - (int) CFUtil.integerOfDate((int) workAreas800.getJan1stDate800()) + 1));
          }
      
      }
