// ******************************************************************
          endptIdOrig810 = reqWorkAreas810.getEndptIdOrig810();
          taraeptBkupEndptId = taraept.getTaraeptBkupEndptId();
//  EVALUATE TRUE
          if  ( work.isTransferEptSelect88110()  ) { 

// *             * Fatal error - taraept sql select error *

// *                 * Taraept error on the original endpoint *
              endptIdOrig810 = reqWorkAreas810.getEndptIdOrig810();
//  IF 810-ENDPT-ID-ORIG = SPACES
              if (        ( allSpaces(endptIdOrig810)   )) { 
//  SET 88-1000-SEND-PRCS-EPTO-SELECT TO TRUE
                  responseParms1000.setSendPrcsEptoSelect881000True(); 
                  
              }
  
//  ELSE
              else { 

// *                 * Taraept error on a backup endpoint *
//  SET 88-1000-SEND-PRCS-EPTB-SELECT TO TRUE
                  responseParms1000.setSendPrcsEptbSelect881000True(); 
                  
              }
//  PERFORM 9400-REPORT-SQL-ERROR
              reportSqlError();/*9400-REPORT-SQL-ERROR*/
//  PERFORM 9444-DISPLAY-TARAEPT-SELECT
              displayTaraeptSelect();/*9444-DISPLAY-TARAEPT-SELECT*/
          }
          else if  (	( itaraept.getTaraeptBkupEndptIdN() == work.getSqlColNull330() )) { 

// *             * Chain broken (bkup-actv-sw=y, column is null) *
//  SET 88-1000-SEND-PRCS-EPTB-BROKEN TO TRUE
              responseParms1000.setSendPrcsEptbBroken881000True(); 
              
//  PERFORM 9900-REPORT-ERROR
              reportError();/*9900-REPORT-ERROR*/
          }
          else if  (		compareChars(taraeptBkupEndptId,endptIdOrig810) == 0 ) { 

// *             * Chain links loop back to the original endpoint *
//  SET 88-1000-SEND-PRCS-EPTB-LOOPS TO TRUE
              responseParms1000.setSendPrcsEptbLoops881000True(); 
              
//  PERFORM 9900-REPORT-ERROR
              reportError();/*9900-REPORT-ERROR*/
          }
  
      
