      public int call(Object[] params) throws Exception {
      
      int len = params.length;
         if (len > 0 && params[0] != null )
            identityParms1000.set((Field)params[0]);
         if (len > 1 && params[1] != null )
            requestParms1000.set((Field)params[1]);
         if (len > 2 && params[2] != null )
            responseParms1000.set((Field)params[2]);
         if (len > 3 && params[3] != null )
            dynamLinkArea1100.set((Field)params[3]);
         // invoke the process and return rc
         return process();
         
      }
      
      public int call(Field... parameters) throws Exception {
         for (int index = 0; index < parameters.length;index++) {
             switch(index) {
              case 0:
                      if(parameters[index] != null ) {
              		if (parameters[index] instanceof IdentityParms1000) {
                       	this.identityParms1000 = ((IdentityParms1000) parameters[index]);
                  	} else {
                       	this.identityParms1000.set(parameters[index]);
                  	}
                  }
                
                  break;
              case 1:
                      if(parameters[index] != null ) {
              		if (parameters[index] instanceof RequestParms1000) {
                       	this.requestParms1000 = ((RequestParms1000) parameters[index]);
                  	} else {
                       	this.requestParms1000.set(parameters[index]);
                  	}
                  }
                
                  break;
              case 2:
                      if(parameters[index] != null ) {
              		if (parameters[index] instanceof ResponseParms1000) {
                       	this.responseParms1000 = ((ResponseParms1000) parameters[index]);
                  	} else {
                       	this.responseParms1000.set(parameters[index]);
                  	}
                  }
                
                  break;
              case 3:
                      if(parameters[index] != null ) {
              		if (parameters[index] instanceof DynamLinkArea1100) {
                       	this.dynamLinkArea1100 = ((DynamLinkArea1100) parameters[index]);
                  	} else {
                       	this.dynamLinkArea1100.set(parameters[index]);
                  	}
                  }
                
                  break;
            }
         }
          return process();
      }
      
      
